-- GENERATED by `wfj generate` from data/gossip/gossip-c6.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["c6049a3acd80c674"] = { "<Benvenuto/Benvenuta> nel rifugio, {name}. C'è chi viene qui con uno scopo, e chi ci è arrivato per caso... Ma qui sembra che ognuno abbia una storia unica da raccontare.", "." },
  ["c6144969f04de715"] = { "Eranikus, Tiranno del Sogno, è entrato nel nostro mondo.", "." },
  ["c61ab01f967adf9d"] = { "Astor? Te la sei presa comoda per arrivare qui, quindi non perdiamo altro tempo, che ne dici?", "." },
  ["c61d6cf008e52434"] = { "Non è servito a molto. Controllo l'altro.", "." },
  ["c62c9c2532f90d30"] = { "Gli alberiani rendono troppo difficile ai pescatori prendere qualcosa nei dintorni di Dolanaar. Ti conviene cercare qualcuno che ti addestri a Darnassus.", "." },
  ["c62e8ceaad08daa8"] = { "La Dea mi ha concesso la saggezza, <straniero/straniera>. Se è il suo volere, la trasmetterò a te.", "." },
  ["c63c10898750813c"] = { "Dunque mi hai trovato. Immagino che tu voglia imparare la soppressione e il controllo.\n\nTi insegnerò molto più di questo... imparerai anche il sacrificio.\n\n<Daio sogghigna.>", "." },
  ["c6442c13afaf8fbe"] = { "L'ombra del Flagello grava ancora su questa terra, sciocchi! Non vincerete mai!", "." },
  ["c64479ceaf960688"] = { "È l'avidità a ricondurti da me.\n\n<Mathredis ride.>\n\nUn saggio draenei una volta mi disse che essa, l'avidità, è l'unica qualità che tutte le razze di questo mondo hanno in comune. Devo dargli ragione.\n\nHai raccolto i componenti elencati nel compendio?", "." },
  ["c644895543371254"] = { "La risata di %s riecheggia nelle sale dell'Ala Nera.", "." },
  ["c651708ab9435622"] = { "Sildinair ha addestrato molte delle ⟦Sentinels=Sentinelle⟧ che sorvegliano la nostra amata città. Non ho dubbi che saprà fare di te <un/una> <guerriero/guerriera>. Cercala alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧, vicino all'ingresso della nostra città.", "." },
  ["c656cfe30371d716"] = { "La rabbia di Ishamuhale scorre in te, {name}.", "." },
  ["c6585f2a85ebfb03"] = { "Se hai attitudine per le arti di {class}, posso addestrarti.", "." },
  ["c65f90075d6bc703"] = { "%s saluta {name} con la mano", "." },
  ["c6602f7e6a636198"] = { "La prima fase è finita. Big Will... fatti avanti!", "." },
  ["c660c1d25a9002e0"] = { "Cosa posso fare per te, {class}?", "." },
  ["c66fec2fa146f987"] = { "È Proudmoore! Via di qui!", "." },
  ["c67426f802552a2d"] = { "Vengo a radere al suolo le vostre basi, clan Lupi Bianchi. Ivus vi punisce per il vostro tradimento!", "." },
  ["c67508299187ef76"] = { "Per favore, pulisciti prima di maneggiare i nostri tomi.", "." },
  ["c6803fa04bd53652"] = { "Devi cercare nelle acque delle ⟦Westfall=Marche Occidentali⟧, verso ovest-nordovest rispetto al punto in cui la ⟦Gold Coast Quarry=Cava della Costa d'Oro⟧ incontra la riva. Un'ancora indica dove, più in là, è affondata una barca, giù in profondità. La pressione sott'acqua lì è feroce; nuotare troppo lontano schiaccerà per lo sfinimento anche il nuotatore più forte.\n\nCerca una formazione naturale che ti aiuti, {name}: qui vicino c'è una fessura piena di bolle, che offre a chi nuota in acque profonde l'occasione di riprendere fiato.", "." },
  ["c683cb7bb764f36a"] = { "Il tuo talento supera il mio, amico. Parla con Tarn, qui: la sua conoscenza del cuoio è molto più grande della mia. Di sicuro accoglierebbe volentieri qualcuno in più da istruire.", "." },
  ["c683d939c6e36871"] = { "No! Lasciaci! Non dobbiamo fallire il nostro compito!", "." },
  ["c684bffc7086aa79"] = { "Krathok, un tempo forgiavo armi e ora vorrei invece imparare la via del fabbro di armature. Mi addestrerai?", "." },
  ["c689733ba6a6499f"] = { "Ho quello che ti serve, {class}.", "." },
  ["c690aa37c6cd0d70"] = { "Basta con queste sciocchezze! Preparati a morire, {race}!", "." },
  ["c6919a1f673710a5"] = { "Parlerei in favore dell'ingresso di mio fratello nell'ordine, anche a rischio della sicurezza dell'ordine. Potrei aiutarlo con le regole dell'ordine, e avrei fiducia nella sua capacità di adattarsi e imparare.", "." },
  ["c6a0b04d9b02148d"] = { "Il ⟦Scarlet Monastery=Monastero Scarlatto⟧ si trova sulle colline a nord-est delle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "." },
  ["c6a1e45de91a1ef1"] = { "Ciao {name}! Grazie per tutto l'aiuto che mi hai dato! Per ora non mi serve nulla, ma chissà cosa ci riserva il futuro?\n\nDivertiti, e ricordati di parlare ai tuoi amici della ⟦Darkmoon Faire=Fiera di Lunacupa⟧!", "." },
  ["c6ae919661d9d715"] = { "Oh! Quasi dimenticavo! Ti ho fatto scivolare in tasca degli Strumenti dei Ladri. Ti serviranno, là dove stai andando.", "." },
  ["c6b28c705f63fabf"] = { "Venite! Venite incontro alla morte... se ne avete il coraggio!", "." },
  ["c6b9ce122d4c2652"] = { "Morte ai Lupi Bianchi!", "." },
  ["c6c1a98f812d6070"] = { "Ah, quindi è così che hanno respinto i ⟦Dark Iron=Ferroscuro⟧ nei livelli inferiori dei Bastioni.", "." },
  ["c6caa98f121a16db"] = { "Tharnariun, ho perso la trappola. Potresti darmene un'altra?", "." },
  ["c6d451ecea70489f"] = { "Betina, vorrei un ⟦Seal of the Dawn=Sigillo dell'Alba⟧ nuovo, per favore!", "." },
  ["c6d6da8a8c07f940"] = { "Fai da guida a uno dei nostri orfani durante la Week of the Wardens! Per l'⟦Horde=Orda⟧!", "." },
  ["c6e220700e4d1b39"] = { "Mi odi, amore mio? Perché ho dovuto distruggere la tua forma vivente, affinché il tuo spirito fosse liberato da un'infelice prigionia.", "." },
  ["c6e7af089c6c3eec"] = { "Pochi arrivano fin qui, e ancora meno vanno oltre. Non diventare un numero nella statistica, {name}.", "." },
  ["c6eed8e0b133cb8a"] = { "Guardati intorno, {name}. Forse troverai qualcosa che mi è sfuggito.", "." },
  ["c6f05988e5383618"] = { "Quando dai i pegni d'amore agli abitanti, riceverai in cambio regali diversi. Alcuni vorrai tenerli e usarli, ma altri si possono raccogliere in un pacchetto e donare al tuo eroe preferito! Va' da Kwee Q. Peddlefeet per consegnarli.\n\nKwee si trova vicino a Bolvar, Magni o Tyrande.", "." },
  ["c6f0f31771741ee5"] = { "In questo mestiere sei più <bravo/brava> di me! Ti serve qualcuno con ancora più esperienza della mia. Sarebbe Ainethil, un'elfa della notte che vive nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["c6f76666fc35d8c4"] = { "Buona giornata a voi due. Vorrei parlare con lord Lescovar.", "." },
})
